cd /home/eval/logs
awk 'BEGIN {
  split("/api/users /api/orders /api/search /api/cart /api/login /healthz /api/items /static/app.js", ep, " ")
  split("GET GET GET POST PUT DELETE", mt, " ")
  x = 7
  for (i = 0; i < 3000; i++) {
    x = (x * 48271) % 2147483647; e = 1 + x % 8
    x = (x * 48271) % 2147483647; m = 1 + x % 6
    x = (x * 48271) % 2147483647; lat = 10 * (1 + x % (40 + 5 * (e % 3))) + (((e == 3 || e == 7) && x % 7 == 0) ? 300 : 0)
    x = (x * 48271) % 2147483647; st = (x % 23 == 0) ? 503 : ((x % 11 == 0) ? 404 : 200)
    x = (x * 48271) % 2147483647; q = x % 10
    path = ep[e]
    if (q == 0) path = path "?page=" (x % 5)
    else if (q == 1 && path != "/healthz") path = path "/"
    ts = sprintf("2026-10-09T%02d:%02d:%02d", 10 + int(i / 3600), int(i / 60) % 60, i % 60)
    if (i % 397 == 396) { print "-- log truncated --"; continue }
    if (i % 251 == 250) { print ts " " mt[m] " " path " 504 -"; continue }
    print ts " " mt[m] " " path " " st " " lat "ms"
